import { match } from "arktype"

const handleResponse = match({
  "{ status: 'success', data: 'object' }": (o: any) => `OK:${JSON.stringify(o.data)}`,
  "{ status: 'error', code: 'number', reason: 'string' }": (o: any) => `ERR ${o.code} ${o.reason}`,
  "{ status: 'pending' }": () => "PENDING",
  default: "assert"
})

console.log(handleResponse({ status: "success", data: { id: 7, name: "widget" } }))
console.log(handleResponse({ status: "error", code: 404, reason: "not found" }))
console.log(handleResponse({ status: "pending" }))
try {
  console.log(handleResponse({ status: "wat" }))
} catch (e) {
  console.log("threw as expected:", (e as Error).message)
}

